class Solution {
public:
    int findBlackPixel(vector<vector<char>>& picture, int target) {
        int m = picture.size(), n = picture[0].size();
        vector<int> col_counts(n, 0);
        unordered_map<string, int> pattern_freq;

        for (int r = 0; r < m; r++) {
            string s(picture[r].begin(), picture[r].end());
            pattern_freq[s]++;
            for (int c = 0; c < n; c++) {
                if (picture[r][c] == 'B') col_counts[c]++;
            }
        }

        int ans = 0;
        for (auto& [row_str, freq] : pattern_freq) {
            if (freq == target) {
                int b_count = 0;
                for (char ch : row_str) if (ch == 'B') b_count++;
                if (b_count == target) {
                    for (int c = 0; c < n; c++) {
                        if (row_str[c] == 'B' && col_counts[c] == target) {
                            ans += target;
                        }
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int findBlackPixel(char[][] picture, int target) {
        int m = picture.length, n = picture[0].length;
        int[] colCounts = new int[n];
        java.util.Map<String, Integer> patternFreq = new java.util.HashMap<>();

        for (int r = 0; r < m; r++) {
            String s = new String(picture[r]);
            patternFreq.put(s, patternFreq.getOrDefault(s, 0) + 1);
            for (int c = 0; c < n; c++) {
                if (picture[r][c] == 'B') colCounts[c]++;
            }
        }

        int ans = 0;
        for (java.util.Map.Entry<String, Integer> entry : patternFreq.entrySet()) {
            if (entry.getValue() == target) {
                String rowStr = entry.getKey();
                int bCount = 0;
                for (int i = 0; i < rowStr.length(); i++) {
                    if (rowStr.charAt(i) == 'B') bCount++;
                }
                if (bCount == target) {
                    for (int c = 0; c < n; c++) {
                        if (rowStr.charAt(c) == 'B' && colCounts[c] == target) {
                            ans += target;
                        }
                    }
                }
            }
        }
        return ans;
    }
}

