var findBlackPixel = function(picture, target) {
    const m = picture.length, n = picture[0].length;
    const colCounts = new Array(n).fill(0);
    const patternFreq = new Map();

    for (let r = 0; r < m; r++) {
        const s = picture[r].join('');
        patternFreq.set(s, (patternFreq.get(s) || 0) + 1);
        for (let c = 0; c < n; c++) {
            if (picture[r][c] === 'B') colCounts[c]++;
        }
    }

    let ans = 0;
    for (const [rowStr, freq] of patternFreq.entries()) {
        if (freq === target) {
            let bCount = 0;
            for (let i = 0; i < rowStr.length; i++) {
                if (rowStr[i] === 'B') bCount++;
            }
            if (bCount === target) {
                for (let c = 0; c < n; c++) {
                    if (rowStr[c] === 'B' && colCounts[c] === target) {
                        ans += target;
                    }
                }
            }
        }
    }
    return ans;
};
